/**
 * Layer rendering.
 *
 * Two strategies, chosen per layer by volume:
 *
 *   - GeoJsonDataSource (entities) for discrete, individually-pickable features: quakes,
 *     volcanoes, fires, aircraft, vessels, tide stations. Dozens to thousands.
 *   - PointPrimitiveCollection for dense lattices: wind, air quality, currents, SST. These are
 *     grid samples with no per-feature identity, and entities at 1000+ points stall the render
 *     loop; primitives are drawn in a single batch.
 *
 * Colour ramps live here so the legend and the pixels cannot drift apart: the legend is
 * generated by calling the same function the renderer uses.
 */

const AQI_BREAKPOINTS = [
  [0, '#22c55e'], [50, '#a3e635'], [100, '#facc15'], [150, '#fb923c'],
  [200, '#f43f5e'], [300, '#a21caf'], [500, '#7c3aed'],
];

const TEMP_BREAKPOINTS = [
  [-2, '#1d4ed8'], [8, '#06b6d4'], [15, '#34d399'],
  [22, '#fde047'], [28, '#fb923c'], [35, '#ef4444'],
];

const WIND_BREAKPOINTS = [
  [2, '#dbeafe'], [6, '#38bdf8'], [12, '#6366f1'],
  [20, '#a855f7'], [35, '#f43f5e'], [60, '#ffffff'],
];

// Currents top out near 3 m/s, so they need their own domain. Borrowing the wind scale made
// every reading land on the single slowest colour, which is a legend that lies.
const CURRENT_BREAKPOINTS = [
  [0, '#dbeafe'], [0.3, '#60a5fa'], [0.6, '#22d3ee'],
  [1.2, '#34d399'], [2, '#fbbf24'], [3, '#f97316'],
];

const FIRE_BREAKPOINTS = [
  [1, '#fde68a'], [10, '#fb923c'], [50, '#f43f5e'], [500, '#7f1d1d'],
];

// Altitudes arrive in metres, so the scale is in metres too; labelling it "km" made the legend
// ticks three orders of magnitude away from the colours they labelled.
const FLIGHT_BREAKPOINTS = [
  [0, '#64748b'], [3000, '#60a5fa'], [10000, '#c084fc'], [13000, '#f43f5e'],
];

const rampCache = new Map();

/** Builds a value -> colour lookup for a set of [threshold, colour] stops. */
function ramp(stops) {
  if (rampCache.has(stops)) return rampCache.get(stops);
  const fn = (value) => {
    if (value === null || value === undefined || Number.isNaN(value)) return '#64748b';
    for (let i = 0; i < stops.length; i += 1) {
      if (value <= stops[i][0]) return stops[i][1];
    }
    return stops[stops.length - 1][1];
  };
  rampCache.set(stops, fn);
  return fn;
}

/** Linear blend between a cool and a hot colour, for magnitude-style scales. */
function magnitudeColour(value, min, max, cold = '#38bdf8', hot = '#ef4444') {
  if (value === null || value === undefined || Number.isNaN(value)) return '#64748b';
  const span = max - min || 1;
  const t = Math.max(0, Math.min(1, (value - min) / span));
  const parse = (hex) => [
    parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16),
  ];
  const [r1, g1, b1] = parse(cold);
  const [r2, g2, b2] = parse(hot);
  const mix = (a, b) => Math.round(a + (b - a) * t);
  return `rgb(${mix(r1, r2)},${mix(g1, g2)},${mix(b1, b2)})`;
}

/**
 * The value a feature should be coloured and sized by, per layer id.
 * Returns null when the layer has no continuous scale.
 */
export function metricOf(layerId, properties) {
  if (!properties) return null;
  switch (layerId) {
    case 'earthquakes': return properties.magnitude ?? null;
    case 'wildfires': return properties.frp ?? properties.frpMw ?? null;
    case 'wind': return properties.windSpeed ?? properties.speed ?? null;
    case 'air-quality': return properties.usAqi ?? properties.aqi ?? null;
    case 'currents': return properties.currentSpeed ?? properties.speed ?? null;
    case 'sea-surface-temperature': return properties.temperature ?? properties.sst ?? null;
    case 'tides': return properties.heightMeters ?? null;
    case 'flights': return properties.altitude ?? properties.baroAltitude ?? null;
    default: return null;
  }
}

/** Legend definition per layer; the swatches come from the same ramps the pixels use. */
const LEGENDS = {
  earthquakes: { type: 'magnitude', min: 0, max: 10, ticks: [0, 2.5, 5, 7, 10], unit: 'M', cold: '#38bdf8', hot: '#ef4444' },
  volcanoes: { type: 'note', text: 'EONET events. Marker size shows time since last observed update.' },
  wildfires: { type: 'ramp', stops: FIRE_BREAKPOINTS, ticks: [1, 10, 50, 500], unit: 'MW' },
  wind: { type: 'ramp', stops: WIND_BREAKPOINTS, ticks: [2, 6, 12, 20, 35, 60], unit: 'm/s' },
  'air-quality': { type: 'ramp', stops: AQI_BREAKPOINTS, ticks: [0, 50, 100, 150, 200, 300, 500], unit: 'US AQI' },
  currents: { type: 'ramp', stops: CURRENT_BREAKPOINTS, ticks: [0, 0.3, 0.6, 1.2, 2, 3], unit: 'm/s' },
  'sea-surface-temperature': { type: 'ramp', stops: TEMP_BREAKPOINTS, ticks: [-2, 8, 15, 22, 28, 35], unit: '°C' },
  tides: { type: 'note', text: 'Station markers. Colour shows predicted height; hover the point readout for turning points.' },
  flights: { type: 'ramp', stops: FLIGHT_BREAKPOINTS, ticks: [0, 3000, 10000, 13000], unit: 'm' },
  vessels: { type: 'note', text: 'AIS position reports. Requires a configured AISStream key.' },
  vegetation: { type: 'note', text: 'NDVI imagery from NASA GIBS, drawn as a WMS raster beneath the vectors.' },
};

export function legendFor(layerId) {
  return LEGENDS[layerId] || null;
}

/**
 * CSS background for a layer's colour tag, generated from the same definition the pixels use.
 * The layer list, the legend and the globe therefore cannot disagree: a ramp layer gets the
 * gradient, not the single flat colour the catalogue happens to advertise.
 */
export function swatchFor(layer) {
  const def = LEGENDS[layer.id];
  if (def && def.type === 'magnitude') {
    return `linear-gradient(to right, ${def.cold}, ${def.hot})`;
  }
  if (def && def.type === 'ramp') {
    return `linear-gradient(to right, ${def.stops.map(([, c]) => c).join(', ')})`;
  }
  return layer.color || '#38bdf8';
}

function colourForFeature(layer, properties) {
  const value = metricOf(layer.id, properties);
  const def = LEGENDS[layer.id];
  if (def && def.type === 'magnitude' && value !== null) {
    return magnitudeColour(value, def.min, def.max, def.cold, def.hot);
  }
  // Read the ramp straight out of the legend table. Keeping a second lookup table here is how
  // the currents layer ended up keyed as "current" and silently fell back to a flat colour
  // while its legend showed a gradient.
  if (def && def.type === 'ramp') return ramp(def.stops)(value);
  return layer.color || '#38bdf8';
}

function sizeForFeature(layer, properties) {
  const value = metricOf(layer.id, properties);
  switch (layer.id) {
    case 'earthquakes':
      return 5 + Math.max(0, Math.min(1, ((value ?? 0) - 2) / 6)) * 15;
    case 'volcanoes': return 11;
    case 'wildfires':
      return 4 + Math.min(1, Math.sqrt(Math.max(0, value ?? 0) / 100)) * 12;
    case 'flights': return 5;
    case 'vessels': return 4;
    case 'tides': return 9;
    case 'air-quality':
    case 'sea-surface-temperature':
    case 'currents':
    case 'wind': return 5;
    default: return 7;
  }
}

function positionOf(feature) {
  const geometry = feature.geometry;
  if (!geometry) return null;
  if (geometry.type === 'Point') {
    const [lon, lat] = geometry.coordinates;
    return Cesium.Cartesian3.fromDegrees(lon, lat);
  }
  if (geometry.type === 'Polygon' && Array.isArray(geometry.coordinates)) {
    const ring = geometry.coordinates[0] || [];
    const points = ring.filter((_, i) => i % Math.max(1, Math.ceil(ring.length / 40)) === 0);
    if (points.length < 3) return null;
    return Cesium.Cartesian3.fromDegreesArray(points.flat());
  }
  return null;
}

/**
 * Renders dense point lattices with a single batched primitive collection.
 * Returns { primitive, index } where index maps "lon,lat" to the feature.
 */
export function renderDense(layer, features, meta) {
  const collection = new Cesium.PointPrimitiveCollection();
  const index = new Map();
  let added = 0;

  for (const feature of features) {
    if (feature.geometry?.type !== 'Point') continue;
    const [lon, lat] = feature.geometry.coordinates;
    const properties = feature.properties || {};
    const value = metricOf(layer.id, properties);
    const colour = Cesium.Color.fromCssColorString(colourForFeature(layer, properties));
    collection.add({
      position: Cesium.Cartesian3.fromDegrees(lon, lat),
      // Explicit key: the local is spelled `colour`, so shorthand `color` would be an
      // undefined variable, and it threw only on the layers that reach this path.
      color: colour,
      pixelSize: sizeForFeature(layer, properties),
      // A hollow core stays legible when thousands of cells overlap, which they do at low zoom.
      outlineColor: Cesium.Color.BLACK.withAlpha(0.45),
      outlineWidth: 1,
      id: { layerId: layer.id, feature },
    });
    index.set(`${lon.toFixed(3)},${lat.toFixed(3)}`, feature);
    added += 1;
  }

  const fragment = new Cesium.PrimitiveCollection();
  fragment.add(collection);
  if (meta?.degraded) fragment.show = true;
  return { primitive: fragment, count: added, index };
}

/** Renders discrete, pickable features as entities. */
export async function renderEntities(layer, features) {
  // load() wants a GeoJSON object; handing it a bare array throws
  // "Unsupported GeoJSON object type: undefined" and yields no entities.
  const source = await Cesium.GeoJsonDataSource.load({ type: 'FeatureCollection', features }, {
    // The payload is already normalised GeoJSON; keep our own properties and ids intact.
    clampToGround: false,
    generateIds: false,
  });

  // EntityCollection is not an array in current Cesium; the elements live in .values.
  const entities = source.entities.values || Array.from(source.entities);
  entities.forEach((entity) => {
    const properties = entity.properties?.getValue?.() || {};
    entity.properties = new Cesium.PropertyBag({
      layerId: layer.id,
      title: properties.name || entity.id || layer.label,
      meta: properties,
    });
    if (entity.point) {
      entity.point.pixelSize = sizeForFeature(layer, properties);
      entity.point.color = Cesium.Color.fromCssColorString(colourForFeature(layer, properties));
      entity.point.outlineColor = Cesium.Color.BLACK.withAlpha(0.6);
      entity.point.outlineWidth = 1.2;
      // Aircraft and vessels read better as an oriented chevron than a dot.
      if (layer.id === 'flights' || layer.id === 'vessels') {
        entity.point = new Cesium.PointGraphics({
          pixelSize: sizeForFeature(layer, properties),
          color: entity.point.color,
          outlineColor: entity.point.outlineColor,
          outlineWidth: 1,
        });
      }
    } else if (entity.polygon) {
      entity.polygon.material = Cesium.Color.fromCssColorString(
        colourForFeature(layer, properties)).withAlpha(0.25);
      entity.polygon.outlineColor = Cesium.Color.fromCssColorString(
        colourForFeature(layer, properties));
    } else if (entity.polyline) {
      entity.polyline.material = Cesium.Color.fromCssColorString(colourForFeature(layer, properties));
      entity.polyline.width = 2;
    }
  });

  return source;
}

/** NDVI cannot be sampled as vectors, so the server returns WMS parameters instead. */
export function imageryFromDescriptor(layer, details) {
  const layerName = details.layer;
  const endpoint = details.endpoint;
  const time = details.time;
  if (!layerName || !endpoint) return null;

  const parameters = { ...(details.style ? { STYLES: details.style } : {}) };
  if (time) parameters.TIME = time;

  let provider;
  try {
    provider = new Cesium.WebMapServiceImageryProvider({
      url: endpoint,
      layers: layerName,
      version: details.version || '1.3.0',
      srs: details.srs,
      format: 'image/png',
      transparent: true,
      tileWidth: 256,
      tileHeight: 256,
      // NASA GIBS publishes NDVI as queryable=0, so it does not implement GetFeatureInfo.
      // Without this, every click on the raster fires a doomed GetFeatureInfo that comes back
      // empty, which is indistinguishable from "you clicked empty ocean" and reads to the user
      // as a broken layer. The backend already reports the layer as an image-only descriptor;
      // this stops the client from contradicting that.
      enablePickFeatures: false,
      parameters,
    });
  } catch (error) {
    console.warn('vegetation imagery unavailable', error);
    return null;
  }
  return { layer, provider, time };
}

export { colourForFeature, sizeForFeature };
